MAP
    NAME "CONFIG_MAP"
    SIZE 800 400
    PROJECTION
        "epsg:4326"
    END
    IMAGECOLOR "#37929E"
    WEB
        IMAGEPATH "/etc/mapserver/tmp/"
        METADATA
            #"ms_enable_modes" "!*" # !* disables all CGI requests
            # "wms_enable_request" "*"
            # "wcs_enable_request" "*"
            # "wfs_enable_request" "*"
            # "ows_enable_request" "*"
        END
    END
    EXTENT -180 -90 180 90
    LAYER
        NAME "countries"
        TYPE POLYGON
        STATUS DEFAULT
        CONNECTIONTYPE FLATGEOBUF
        DATA "data/naturalearth/ne_110m_admin_0_countries.fgb"

        CLASS
            STYLE
                COLOR "#C7CAB0"
                OUTLINECOLOR 255 255 255
                WIDTH 0.1
            END
        END
    END
END